// memset/memcpy through the compiler's intrinsics, narrow arguments and
// narrow return values.
// The memset libcall generated by LLVM passes its value as an 8-bit type,
// which the C implementation must receive correctly as an int.
// expect-exit: 0
#include <string.h>
#include <stdint.h>

static unsigned char buf[300];
volatile int n = 250, v = 0xAB;
volatile unsigned char cv = 0x5C;

__attribute__((noinline)) static int narrow_args(signed char a, unsigned char b,
                                                 short c, unsigned short d) {
  return a + b + c + d;
}

// Narrow return values are widened to 32 bits on both sides of a call; the
// caller must not store a wide value into a narrow slot.
__attribute__((noinline)) static unsigned char ret_u8(void) { return cv; }
__attribute__((noinline)) static signed char ret_s8(void) { return (signed char)v; }
__attribute__((noinline)) static short ret_s16(void) { return (short)(v * 100); }
__attribute__((noinline)) static unsigned narrow_rets(void) {
  unsigned char a[4] = {1, 2, 3, 4};
  unsigned char r = ret_u8();          // a[] must survive the call result store
  short s = ret_s16();
  signed char c = ret_s8();
  return r + a[0] + a[1] * 10 + a[2] * 100 + a[3] * 1000 + (unsigned)(int)s * 7 + (unsigned)(int)c;
}

int main(void) {
  memset(buf, v, n);
  for (int i = 0; i < 300; i++)
    if (buf[i] != (i < 250 ? 0xAB : 0)) return 1;
  memset(buf + 10, cv, 7);
  for (int i = 10; i < 17; i++)
    if (buf[i] != 0x5C) return 2;
  // A loop that the optimiser turns into a memset of a variable byte.
  for (int i = 0; i < n; i++)
    buf[i] = (unsigned char)(v + 1);
  for (int i = 0; i < 250; i++)
    if (buf[i] != 0xAC) return 3;
  unsigned char src[32];
  for (int i = 0; i < 32; i++) src[i] = (unsigned char)(200 + i);
  memcpy(buf + 1, src, 32);
  if (buf[1] != 200 || buf[32] != 231) return 4;
  if (narrow_args(-3, 250, -1000, 60000) != 59247) return 5;
  if (narrow_rets() != 124028u) return 6;
  return 0;
}
